async function loadAvatars(){const epoch=state.epoch;for(const m of state.board?.members||[]){if(epoch!==state.epoch)return;if(!m.hasAvatar)continue;if(state.avatars.get(m.id)?.version===m.avatarVersion)continue;try{const r=await apiFetch(`/api/avatar/${m.id}`);if(!r.ok)continue;const blob=await r.blob();if(epoch!==state.epoch)return;const url=URL.createObjectURL(blob),old=state.avatars.get(m.id);if(old)URL.revokeObjectURL(old.url);state.avatars.set(m.id,{url,version:m.avatarVersion});document.querySelectorAll(`[data-avatar="${m.id}"]`).forEach(e=>{e.innerHTML=`<img src="${url}" alt="${esc(m.nickname)}的头像">`;});}catch{}}loadRecordPhotos();}
const tabs=[['feed','球场动态'],['members','球友名片'],['culture','群里那些梗'],['my','成长档案']];
function nav(){return tabs.map(([key,label])=>`<button class="nav-item ${state.tab===key?'active':''}" data-action="tab" data-tab="${key}" ${state.tab===key?'aria-current="page"':''}>${icon(key)}<span>${label}</span></button>`).join('');}
function stats(person){const b=state.board;return `<div class="stats"><div class="stat"><div class="stat-label">${icon('feed')}${person?'我的打球记录':'群里的打球记录'}</div><div class="stat-number">${person?person.record_count:b.totals.records}<small>次</small></div></div><div class="stat"><div class="stat-label">${icon('clock')}${person?'我的球场时光':'累计球场时光'}</div><div class="stat-number">${hours(person?person.minutes:b.totals.minutes)}<small>小时</small></div></div><div class="stat"><div class="stat-label">${icon('members')}${person?'我的球场徽章':'已加入的球友'}</div><div class="stat-number">${person?(Number(person.record_count)>=10?'10场':Number(person.record_count)>=5?'5场':Number(person.record_count)>=1?'首场':'待解锁'):b.members.length}<small>${person?'纪念':'位'}</small></div></div></div>`;}
function recordCard(r){const b=state.board,m=member(r.member_id),mine=r.member_id===b.me,reactions=b.cheers.filter(c=>c.record_id===r.id);return `<article class="record"><div class="record-head"><div class="identity">${avatar(m)}<div><strong>${esc(m?.nickname||r.nickname)}${mine?' <span class="optional">· 我</span>':''}</strong><small>${esc(r.mood)}</small></div></div><time class="record-date" datetime="${esc(r.play_date)}">${esc(r.play_date.slice(0,4))} / ${day(r.play_date)}</time></div><div class="record-tags"><span class="tag">${icon('clock')} ${r.minutes} 分钟</span>${r.venue?`<span class="tag">${esc(r.venue)}</span>`:''}<span class="tag mood">🎾 ${esc(r.mood)}</span></div>${r.note?`<p class="record-note">${esc(r.note)}</p>`:'<p class="record-note">又攒下了一场球场时光。</p>'}${r.partners?`<p class="record-partners">一起打球：${esc(r.partners)}</p>`:''}${Growth.recordDetails(r)}${recordPhotoGallery(r)}${Hexagon.recordChip(r)}<div class="record-bottom"><div class="cheers">${['👏','🔥','🎾'].map(e=>`<button class="cheer ${reactions.some(c=>c.member_id===b.me&&c.emoji===e)?'chosen':''}" data-action="cheer" data-id="${r.id}" data-emoji="${e}" aria-label="${e==='👏'?'鼓掌':e==='🔥'?'手感火热':'一起打球'}，${reactions.filter(c=>c.emoji===e).length} 人">${e} <span>${reactions.filter(c=>c.emoji===e).length||''}</span></button>`).join('')}</div>${mine||b.me===b.club.ownerId?`<div class="record-tools">${mine?`<button class="text-button" data-action="edit-record" data-id="${r.id}">编辑</button>`:''}<button class="text-button danger" data-action="delete-record" data-id="${r.id}">删除</button></div>`:''}</div></article>`;}
function emptyRecord(personal=false){return `<div class="empty"><span class="empty-mark">🎾</span><h3>${personal?'你的故事，从这一场开始':'这里还差第一场球'}</h3><p>${personal?'记下打球时长和今天的手感，下次回看会很有意思。':'打了多久、和谁一起、有什么趣事？让群里的网球故事慢慢攒起来。'}</p><button class="primary" data-action="record">${icon('plus')}记一场球</button></div>`;}
function aside(){const b=state.board;return `<aside class="aside"><div class="club-card"><p class="eyebrow">OUR COURT, OUR CLUB</p><h3>${esc(b.club.slogan||'每一场球，都算数。')}</h3><p>胜负留在球场，快乐记在这里。<br>你的搭子、你的故事、你们的梗。</p><button class="primary lime" data-action="invite">${icon('share')}邀请群友一起记</button></div><div class="mini-card"><div class="section-heading"><h3>在这里的搭子</h3><button class="text-button" data-action="tab" data-tab="members">看全部</button></div><div class="mini-members">${b.members.slice(0,8).map(m=>avatar(m)).join('')}</div><p>${b.members.length} 位球友，慢慢打成一个圈。</p></div><p class="hint">用自己的昵称记自己的球，<br>让每一次挥拍都有个着落。</p></aside>`;}
function feed(){const b=state.board;return `<div class="page-heading"><div><p class="eyebrow">COURT NOTES / 群里的网球小本本</p><h1>${esc(b.club.name)}</h1><p class="subtext">看看大家最近打了什么球。</p></div><div class="heading-actions"><button class="primary" data-action="training">${icon('plus')}记录训练</button><button class="secondary" data-action="record">记一场球</button></div></div>${joinBanner()}${Growth.checkinBar()}${stats()}<div class="workspace"><section><div class="section-heading"><h2>最近的球场故事</h2><button class="text-button" data-action="refresh">${icon('refresh')}刷新</button></div><div class="feed">${b.records.length?b.records.map(recordCard).join(''):emptyRecord()}</div>${Number(b.totals.records)>500?'<p class="hint">这里展示最近 500 条记录，累计统计包含全部记录。</p>':''}</section>${aside()}</div>`;}
function joinBanner(){if(state.board.me)return '';const pending=registrationAttempt(state.board.club.id);if(pending)return `<div class="join-banner"><div><strong>继续保存你的原身份</strong><p>${esc(pending.nickname)} 的名片已保留，上次保存还没有收到完整回复。</p></div><button class="primary" data-action="register" data-club="${esc(pending.clubId)}">继续保存我的身份</button></div>`;const original=state.legacyClub;return `<div class="join-banner"><div><strong>${original?'本设备还有你的原名片':'给自己一张球友名片'}</strong><p>${original?`${esc(original.nickname)} 的记录和头像还在，连接当前身份后继续使用。`:'取个群昵称，就能记录打球、给搭子鼓掌。'}</p></div><div><button class="primary" data-action="${original?'bind-legacy':'profile'}">${original?'连接本设备的原名片':'加入这群搭子'}</button>${!state.account?'<button class="text-button" data-action="login">开始使用 / 找回名片</button>':''}${canUsePagesBridge&&remoteApi&&!state.account?'<button class="text-button" data-action="link-pages">使用原页面的名片</button>':''}</div></div>`;}
function badge(m){return Number(m.record_count)>=10?'十场常客':Number(m.record_count)>=5?'球场熟面孔':Number(m.record_count)>=1?'首场留念':'刚刚入场';}
function members(){const b=state.board;return `<div class="page-heading"><div><p class="eyebrow">MEET THE CREW</p><h1>这一群，都是搭子。</h1><p class="subtext">${b.members.length} 位球友，每个人都有自己的球风。</p></div><button class="primary" data-action="${b.me?'profile':'profile'}">${icon('my')}${b.me?'编辑我的名片':'建立我的名片'}</button></div><div class="member-grid">${b.members.map(m=>`<article class="member-card"><div class="member-top">${avatar(m,true)}${Hexagon.badge(m)}</div><h3>${esc(m.nickname)}${m.id===b.me?' <span class="optional">· 我</span>':''}</h3><p class="bio">${esc(m.bio||'先打球，慢慢熟。')}</p>${Hexagon.memberSummary(m,true)}<div class="member-numbers"><div><strong>${m.record_count}</strong><span>场记录</span></div><div><strong>${hours(m.minutes)}</strong><span>小时</span></div></div></article>`).join('')}</div>`;}
function culture(){const b=state.board;return `<div class="page-heading"><div><p class="eyebrow">ONLY WE GET IT</p><h1>群里那些梗。</h1><p class="subtext">口头禅、球场名场面，懂的人自然懂。</p></div><button class="primary" data-action="culture">${icon('plus')}留下一句群内梗</button></div>${joinBanner()}${b.culture.length?`<div class="culture-grid">${b.culture.map(p=>`<article class="culture-card"><p class="culture-quote">“${esc(p.content)}”</p><div class="culture-credit"><div class="identity">${avatar(member(p.member_id))}<div><strong>${esc(member(p.member_id)?.nickname||p.nickname)}</strong><small>${day(p.created_at.slice(0,10))}</small></div></div>${p.member_id===b.me?`<button class="text-button danger" data-action="delete-culture" data-id="${p.id}">删除</button>`:''}</div></article>`).join('')}</div>`:'<div class="empty"><span class="empty-mark">💬</span><h3>只有你们懂的那一句</h3><p>还没有群内梗。把球场上的名场面、群里的口头禅留在这里。</p><button class="primary" data-action="culture">留下一句</button></div>'}`;}
function mine(){const m=me();if(!m)return `<div class="page-heading"><div><p class="eyebrow">MY COURT NOTES</p><h1>我的小本本</h1></div></div>${joinBanner()}<div class="empty"><span class="empty-mark">👋</span><h3>先让搭子认识你</h3><p>昵称、头像，再加一句你的球场宣言。</p><button class="primary" data-action="profile">建立球友名片</button></div>`;const records=state.board.records.filter(r=>r.member_id===m.id);return `<div class="page-heading"><div><p class="eyebrow">MY COURT NOTES</p><h1>我的小本本</h1><p class="subtext">每一次出门打球，都是一点小小的进步。</p></div><button class="primary" data-action="record">${icon('plus')}记一场球</button></div><div class="my-card"><div class="identity">${avatar(m,true)}<div><h2>${esc(m.nickname)}</h2><small>${esc(m.bio||'先打球，慢慢熟。')}</small></div></div><button class="secondary" data-action="profile">编辑我的名片</button></div>${monthlySection(m)}${Hexagon.memberSummary(m)}${stats(m)}<div class="section-heading"><h2>我记下的球</h2><span class="optional">${badge(m)}</span></div><div class="feed">${records.length?records.map(recordCard).join(''):emptyRecord(true)}</div>`;}
function accountAlias(){return (state.clubs.find(c=>c.id===state.board?.club.id)?.nickname||state.clubs[0]?.nickname||state.account?.displayName||'').slice(0,20);}
function accountControls(){return state.account?`<button class="small-button" data-action="home">我的群</button><button class="small-button" data-action="identity">我的身份</button><button class="text-button" data-action="login">切换身份</button><button class="text-button" data-action="logout">退出本设备</button>`:`${me()||registrationAttempt(state.board?.club.id)?'<button class="small-button" data-action="register">保存我的身份（免密码）</button>':''}<button class="text-button" data-action="login">登录账号</button>`;}
function identityStrip(){const m=me();return `<div class="identity-strip"><div><strong>${m?`当前名片：${esc(m.nickname)}`:'还没有建立球友名片'}</strong><small>${state.account?`已记住身份 · ${esc(state.account.displayName)}`:m?'本设备名片 · 可保存为免密码身份':'访客 · 可用恢复码找回自己的群'}</small></div><div class="identity-actions">${accountControls()}</div></div>`;}
function accountPanel(){const m=me();return `<section class="account-panel"><div><strong>${state.account?'这个设备已经记住你':'让这张名片跟着你'}</strong><p>${state.account?`当前身份：${esc(state.account.displayName)}。使用邮箱和密码，或本人恢复码，在其他设备登录。`:m?'保存免密码身份，换手机或浏览器时用恢复码找回原名片、头像和训练记录。':'用恢复码找回已有身份，或先建立自己的球友名片。'}</p></div><div class="identity-actions">${accountControls()}</div></section>`;}
function growthPage(){return `${accountPanel()}${Growth.page()}`;}
function pendingRegistrations(){if(!state.registrationAttempts.length)return '';return `<section class="account-clubs" id="pending-registrations">${state.registrationAttempts.map(a=>`<div class="home-login-note"><div><strong>继续保存 ${esc(a.nickname)} 的身份</strong><p>${esc(a.name)} 的名片已保留，上次保存还没有收到完整回复。</p></div><button class="primary" data-action="register" data-club="${esc(a.clubId)}">继续保存我的身份</button></div>`).join('')}</section>`;}
function pendingClaims(){const claims=state.claims.filter(c=>!state.clubs.some(joined=>joined.id===c.id));if(!claims.length)return '';return `<section class="account-clubs pending-claims" id="pending-claims"><div class="section-heading"><h2>本设备待连接的原名片</h2><span class="optional">${claims.length} 张</span></div><p class="form-helper">这些原名片的头像和记录都保留着。确认连接到自己的身份后，就能在其他设备找回。</p><div class="club-list">${claims.map(c=>`<button class="club-list-item" data-action="bind-legacy" data-club="${esc(c.id)}"><span class="club-list-ball">🎾</span><span><strong>${esc(c.name)}</strong><small>${esc(c.nickname)}${c.isOwner?' · 群主':''}</small></span><span class="club-list-go">连接原名片 →</span></button>`).join('')}</div></section>`;}
function clubList(){if(!state.account&&!state.clubs.length)return '';return `<section class="account-clubs" id="account-clubs"><div class="section-heading"><h2>${state.account?'我的群':'本设备的球友名片'}</h2><span class="optional">${state.clubs.length} 个群</span></div>${!state.account?'<p class="form-helper">为原名片保存免密码身份，以后自动进入，换设备也能找回。</p>':''}${state.clubs.length?`<div class="club-list">${state.clubs.map(c=>`<button class="club-list-item" data-action="${state.account?'open-club':'register'}" data-club="${esc(c.id)}"><span class="club-list-ball">🎾</span><span><strong>${esc(c.name)}</strong><small>${esc(c.nickname)}${c.isOwner?' · 群主':''}</small></span><span class="club-list-go">${state.account?'打开小本本 →':'保存我的身份 →'}</span></button>`).join('')}</div>`:'<div class="club-list-empty"><p>还没有加入的群。点开朋友的邀请链接，或为你们创建一本。</p></div>'}</section>`;}
function welcome(){document.title='网球搭子 · 我的群';app.innerHTML=`<main class="welcome"><div class="welcome-top"><div class="brand"><span class="brand-icon">🎾</span><div><strong>网球搭子</strong><small>COURT NOTES</small></div></div><div class="welcome-account">${state.account?`<span>已记住 <strong>${esc(state.account.displayName)}</strong></span><div><button class="text-button" data-action="identity">我的身份</button><button class="text-button" data-action="login">切换身份</button><button class="text-button" data-action="logout">退出本设备</button></div>`:'<button class="secondary" data-action="login">开始使用 / 找回名片</button>'}</div></div>${readQuickStart()?'<div class="home-login-note"><div><strong>继续保存刚刚建立的名片</strong><p>恢复码还没有完整收到，请继续保存。</p></div><button class="primary" data-action="quick-signup">继续保存名片</button></div>':''}${clubList()}${pendingRegistrations()}${pendingClaims()}${!state.account?'<div class="home-login-note"><div><strong>已经有自己的球友名片？</strong><p>平时自动进入，换设备时用只由你保存的恢复码找回。</p></div><button class="primary" data-action="login">开始使用 / 找回名片</button></div>':''}<div class="welcome-grid"><div class="welcome-copy"><p class="eyebrow">一起打球，也一起记住。</p><h1>你们的搭子。<br>你们的<em>网球故事。</em></h1><p>为微信群开一本共享小本本。每个人自己记球，用自己的头像、昵称，留下这一群人的独特味道。</p><div class="welcome-notes"><div class="welcome-note"><span>01</span><strong>记下日期、时长、搭档和感想</strong></div><div class="welcome-note"><span>02</span><strong>上传头像，拥有自己的球友名片</strong></div><div class="welcome-note"><span>03</span><strong>给搭子鼓掌，收藏只有你们懂的梗</strong></div></div></div><section class="create-card"><h2>${state.account?'再为你们开一本':'给你们的群开一本'}</h2><form id="create-form" class="form"><div><label for="club-name">群名</label><input id="club-name" name="name" value="网球搭子" maxlength="24" required autocomplete="off"></div><div><label for="club-slogan">群口号 <span class="optional">选填，以后可以改</span></label><input id="club-slogan" name="slogan" placeholder="比如：球可以出界，快乐不能。" maxlength="80"></div><div><label for="founder-name">你的群昵称</label><input id="founder-name" name="nickname" value="${esc(accountAlias())}" placeholder="搭子们平时怎么叫你？" maxlength="20" required autocomplete="nickname"></div><div class="form-error" role="alert"></div><button class="primary" type="submit">创建群小本本</button><p class="form-helper">创建后复制邀请链接，发到微信群。<br>${state.account?'新群会加入你的身份，昵称可以按每个群分别填写。':'只填昵称建立名片，建群资料会保留。'}</p></form></section></div><p class="welcome-footer">组内资料仅已加入的成员可见。每个人使用自己的账号，修改自己的记录。</p></main>`;const createForm=$('#create-form');if(state.createDraft)for(const [key,value] of Object.entries(state.createDraft))if(createForm.elements[key])createForm.elements[key].value=value;createForm.addEventListener('input',()=>{state.createDraft=Object.fromEntries(new FormData(createForm));});createForm.addEventListener('submit',async e=>{e.preventDefault();if(!state.account||readQuickStart()){state.createDraft=Object.fromEntries(new FormData(e.currentTarget));openQuickAuth();return;}const f=e.currentTarget;await submit(f,async()=>{const v=Object.fromEntries(new FormData(f));const r=await request('/api/clubs','POST',v);state.createDraft=null;if(!validToken(r.invite))throw new Error('小本本已创建，但邀请链接没有完整收到，请刷新后进入。');resetView();state.invite=r.invite;state.invalidInvite=false;state.club=null;history.replaceState(null,'',`${appBase}#g=${encodeURIComponent(r.invite)}`);render();await loadAccount();await load();if(!state.board)throw new Error(state.error||'小本本已创建，请刷新后进入。');toast('小本本开好了，把搭子们叫进来！');if(!state.account){const saved=await autoSaveIdentity(true);if(saved)return;}await openInvite();});});}
function invalidInvitePage(){document.title='网球搭子 · 邀请链接无效';app.innerHTML=`<main class="welcome"><div class="brand"><span class="brand-icon">🎾</span><strong>网球搭子</strong></div><section class="account-gate" id="invalid-invite"><h1>邀请链接无效或不完整</h1><p>请让群友重新复制完整邀请链接，再从那条链接进入。</p><div class="form-actions"><button class="primary" data-action="home">回首页 / 我的群</button><button class="secondary" data-action="login">开始使用 / 找回名片</button></div></section></main>`;}
function render(){if(state.publicToken){renderPublicCard();return;}if(state.preview&&!state.preview.joined){renderInviteGate();return;}if(state.invalidInvite){invalidInvitePage();return;}if(!state.authReady){app.innerHTML=`<main class="welcome"><div class="brand"><span class="brand-icon">🎾</span><strong>网球搭子</strong></div>${state.authError?`<div class="error-panel"><p>${esc(state.authError)}</p><button class="secondary" data-action="refresh-auth">重试</button></div>`:'<p class="loading-line">正在找回你的身份和小本本…</p>'}</main>`;return;}if(!hasClub()){welcome();return;}if(!state.board){app.innerHTML=`<main class="welcome"><div class="brand"><span class="brand-icon">🎾</span><strong>网球搭子</strong></div>${state.club&&!state.invite&&!state.account?'<div class="account-gate"><h1>找回身份，继续记球。</h1><p>使用加入这个群时只由你保存的私密恢复码。</p><button class="primary" data-action="login">开始使用 / 找回名片</button></div>':state.error?`<div class="error-panel"><p>${esc(state.error)}</p><button class="secondary" data-action="refresh">重试</button></div>`:'<p class="loading-line">正在翻开群里的小本本…</p>'}<button class="text-button" data-action="home">返回首页 / 我的群</button></main>`;return;}const b=state.board,m=me();app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-icon">🎾</span><div><strong>网球搭子</strong><small>COURT NOTES</small></div></div><nav class="side-nav" aria-label="主导航">${nav()}</nav><div class="sidebar-bottom"><div class="side-note"><strong>SEE YOU ON COURT.</strong>我们下次，球场见。</div><button class="small-button" data-action="home">首页 / 我的群</button>${m?.id===b.club.ownerId?'<button class="small-button" data-action="management">管理小组</button>':''}<button class="small-button" data-action="invite">${icon('share')}邀请搭子</button></div></aside><main class="main"><header class="topbar"><span class="topbar-date">${new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date())}</span><div class="top-actions">${m?.id===b.club.ownerId?'<button class="small-button" data-action="management">管理小组</button>':''}<button class="small-button" data-action="invite">${icon('share')}邀请</button><button class="icon-button" data-action="profile" aria-label="${m?'编辑我的名片':'建立我的名片'}">${avatar(m)}</button></div></header>${identityStrip()}${state.error?`<div class="error-panel"><p>${esc(state.error)}</p><button class="secondary" data-action="refresh">重试</button></div>`:''}${({feed,members,culture,my:growthPage}[state.tab]||feed)()}</main><nav class="mobile-nav" aria-label="手机主导航">${nav()}</nav></div>`;}
function modal(title,content,eyebrow='COURT NOTES'){if(dialog.open)closeDialog();$('#dialog-title').textContent=title;$('#dialog-eyebrow').textContent=eyebrow;$('#dialog-body').innerHTML=content;dialog.showModal();dialog.querySelector('input:not([type=hidden]),textarea,button')?.focus();}
$('#close-dialog').onclick=()=>closeDialog();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
async function submit(form,action){const btn=form.querySelector('button[type=submit]'),error=form.querySelector('.form-error');if(btn.disabled)return;btn.disabled=true;error.textContent='';try{await action();}catch(e){error.textContent=e.message;error.scrollIntoView({block:'nearest'});}finally{btn.disabled=false;}}
function requireMember(){if(!state.board?.me){openProfile();return false;}return true;}
function actionButtons(label){return `<div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="secondary" data-action="close">取消</button><button type="submit" class="primary">${label}</button></div>`;}
function normalizeRecoveryCode(value){const compact=String(value||'').toUpperCase().replace(/[\s-]/g,'');return /^TC[0-9A-F]{40}$/.test(compact)?'TC-'+compact.slice(2).match(/.{8}/g).join('-'):null;}
let privateRecoveryCode=null;
function clearPrivateRecovery(){privateRecoveryCode=null;for(const input of document.querySelectorAll('#saved-recovery-code,#recovery-code')){input.value='';input.defaultValue='';input.textContent='';}}
function closeDialog(){clearPrivateRecovery();dialog.close();$('#dialog-body').replaceChildren();}
dialog.addEventListener('cancel',clearPrivateRecovery);dialog.addEventListener('close',()=>{if(!dialog.open){clearPrivateRecovery();$('#dialog-body').replaceChildren();}});window.addEventListener('pagehide',clearPrivateRecovery);
function showRecoveryCode(code,{offerInvite=false}={}){const normalized=normalizeRecoveryCode(code);if(!normalized){toast('身份已保存。请在“我的身份”中重新生成恢复码。');return;}modal('保存你的私密恢复码',`<div class="recovery-card"><p><strong>${esc(state.account?.displayName||'你的身份')}</strong> 已经记住了。平时自动进入；换设备或缓存丢失时，用这份恢复码找回原名片和记录。</p><label for="saved-recovery-code">只由你保存的恢复码</label><textarea id="saved-recovery-code" class="recovery-code" readonly spellcheck="false" aria-label="只由本人保存的私密恢复码">${esc(normalized)}</textarea><p class="recovery-warning">只自己保存，不要发到群里。拿到这份码的人能进入你的身份。</p><div class="recovery-save-actions"><button class="secondary" data-action="copy-recovery">复制恢复码</button><button class="secondary" data-action="download-recovery">下载恢复码</button></div><p class="form-helper">关闭后不再显示原码。原设备仍能自动进入时，可以在“我的身份”中重新生成。</p><div class="form-actions"><button class="primary" data-action="${offerInvite?'recovery-invite':'close'}">${offerInvite?'已保存，去邀请搭子':'我已保存，继续记球'}</button></div></div>`,'ONLY FOR YOU');privateRecoveryCode=normalized;}
async function copyRecovery(){const input=$('#saved-recovery-code');if(!privateRecoveryCode||!input)return;try{await navigator.clipboard.writeText(privateRecoveryCode);toast('恢复码已复制，只自己保存，不要发到群里。');}catch{input.focus();input.select();try{toast(document.execCommand('copy')?'恢复码已复制，请私下保存。':'长按已选中的恢复码，选择复制。');}catch{toast('长按已选中的恢复码，选择复制。');}}}
function downloadRecovery(){if(!privateRecoveryCode)return;const text=`网球搭子 · 私密恢复码\n身份：${state.account?.displayName||''}\n恢复码：${privateRecoveryCode}\n\n平时自动进入；换设备或缓存丢失后，在网页“用恢复码找回我的身份”中填写。\n只自己保存，不要发到群里。拿到这份码的人能进入你的身份。\n网页：${appBase}\n`,url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='网球搭子-私密恢复码.txt';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('恢复码文件已下载，请只由自己保存。');}
async function finishIdentity(result,{clubId,openClub=false}={}){if(!result.account)throw new Error('身份没有保存完成，请重试。');clearQuickStart();if(state.invalidInvite){state.invite=null;state.club=null;state.invalidInvite=false;history.replaceState(null,'',appBase);}resetView();state.account=result.account;state.clubs=[];state.authReady=true;state.authError=null;state.linkIntent=null;if(openClub&&!state.invite&&validClub(clubId)){state.club=clubId;history.replaceState(null,'',`${appBase}#c=${encodeURIComponent(clubId)}`);}render();await loadAccount();await load();}
async function registerIdentity(clubId,legacySession){if(!validClub(clubId))throw new Error('请先打开自己的群，再保存身份。');const attempt=rememberRegistrationAttempt(clubId,legacySession),path=`/api/auth/register?club=${encodeURIComponent(clubId)}`,result=await request(path,'POST',{registrationNonce:attempt.nonce},validToken(attempt.legacySession)?{legacySession:attempt.legacySession}:{});if(!result.account||!normalizeRecoveryCode(result.recoveryCode))throw new Error('没有收到完整的身份回复，请继续保存，原名片会保留。');rememberLegacyClaims(result,clubId);forgetRegistrationAttempt(clubId);await finishIdentity(result,{clubId,openClub:true});return result.recoveryCode;}
async function autoSaveIdentity(offerInvite=false){if(state.account)return false;try{const code=await registerIdentity(state.board?.club.id);showRecoveryCode(code,{offerInvite});return true;}catch(e){render();toast(`名片已保留，身份还没有保存完成：${e.message}`);return false;}}
function openSaveIdentity(clubId){const selected=clubId||state.board?.club.id||state.clubs[0]?.id,pending=registrationAttempt(selected),claim=state.claims.find(c=>c.id===selected),m=me(),legacy=state.legacyClub?.id===selected?state.legacyClub:claim;if(state.account&&!pending){if(legacy)openBindLegacy(selected);else openIdentity();return;}if(!validClub(selected)||(!m&&!state.clubs.some(c=>c.id===selected)&&!legacy&&!pending)){toast('先建立自己的球友名片，再保存免密码身份。');return;}const nickname=pending?.nickname||m?.nickname||legacy?.nickname||state.clubs.find(c=>c.id===selected)?.nickname;modal(pending?'继续保存我的身份':'保存我的身份（免密码）',`<form id="save-identity-form" class="form"><p class="auth-intro">为 <strong>${esc(nickname||'你的球友名片')}</strong> 保存免密码身份，保留原来的头像、记录和群主身份。</p><p class="profile-help">平时这个设备会自动进入。换设备或清除缓存后，用只由你保存的私密恢复码找回。保存后会显示恢复码，请只自己保存，不要发群。</p>${actionButtons(pending?'继续保存并显示私密恢复码':'保存并生成私密恢复码')}</form>`,'MY TENNIS IDENTITY');$('#save-identity-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{let code;try{code=await registerIdentity(selected,legacy?.token);}catch(error){if(pending&&!validToken(pending.legacySession)&&[401,409].includes(error.status)){await loadAccount();if(state.account&&state.clubs.some(c=>c.id===selected)){openRenewRecovery({pendingClub:selected});return;}}throw error;}closeDialog();showRecoveryCode(code,{offerInvite:!!state.board&&state.board.me===state.board.club.ownerId});});};}
function openRecoveryLogin(){modal('用恢复码找回我的身份',`<form id="auth-form" class="form"><p class="auth-intro">粘贴只由你保存的私密恢复码，找回自己的群、名片和成长记录。</p><div><label for="recovery-code">我的私密恢复码</label><input id="recovery-code" name="recoveryCode" type="password" required maxlength="128" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="TC-…"><p class="form-helper">TC 开头，后面是五组 8 位字符。支持直接粘贴。</p></div><button class="text-button recovery-help" type="button" data-action="recovery-help">我没有恢复码</button><button class="text-button" type="button" data-action="quick-signup">第一次使用？填写昵称建立名片</button>${actionButtons('找回我的身份')}</form>`,'MY TENNIS IDENTITY');$('#auth-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;await submit(form,async()=>{const recoveryCode=normalizeRecoveryCode(form.elements.recoveryCode.value);if(!recoveryCode)throw new Error('恢复码格式不完整，请粘贴 TC 开头的完整恢复码。');const result=await request('/api/auth/login','POST',{recoveryCode});form.elements.recoveryCode.value='';closeDialog();await finishIdentity(result);toast('身份找回了，欢迎回到球场。');});};}
function openRecoveryHelp(){modal('我没有恢复码',`<p>请回到仍能自动进入的原手机或浏览器，在“我的身份”里重新生成恢复码，再用它连接新设备。</p><p class="profile-help">昵称和头像不能证明是本人。为了保留每个人自己的记录，不能按名字选择或找回别人的身份。</p>${state.account?'<div class="form-actions"><button class="primary" data-action="renew-recovery">在本设备重新生成恢复码</button></div>':'<div class="form-actions"><button class="primary" data-action="close">我知道了</button></div>'}`,'MY TENNIS IDENTITY');}
function openIdentity(){if(!state.account){openRecoveryLogin();return;}modal('我的账号',`<div class="identity-detail"><p>当前身份：<strong>${esc(state.account.displayName)}</strong></p>${me()?`<p>本群名片：<strong>${esc(me().nickname)}</strong></p>`:''}<p class="profile-help">这个浏览器会自动记住你。换设备时，用私密恢复码找回名片、照片和历史。恢复码只自己保存。</p><div class="form-actions">${state.account.hasEmail?'<button class="secondary" data-action="credentials">更新原邮箱和密码</button>':''}<button class="secondary" data-action="login">切换身份</button><button class="secondary" data-action="renew-recovery">重新生成恢复码</button><button class="primary" data-action="close">继续记球</button></div></div>`,'MY TENNIS IDENTITY');}
function openRenewRecovery({pendingClub=null}={}){if(!state.account){openRecoveryLogin();return;}modal(pendingClub?'身份已记住，生成新的恢复码？':'重新生成恢复码？',`<form id="renew-recovery-form" class="form">${pendingClub?`<p>服务器已记住身份 <strong>${esc(state.account.displayName)}</strong>，但上次的恢复码没有完整收到，重试凭据也已无法使用。</p>`:''}<p>生成新恢复码后，<strong>旧恢复码会立即失效</strong>。已经记住你的设备仍可继续使用，名片和记录会保留。</p><p class="profile-help">请确认后保存新码，只由自己保管，不要发群。</p>${actionButtons('确认，让旧码失效并生成新码')}</form>`,'ONLY FOR YOU');$('#renew-recovery-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{const result=await request('/api/auth/recovery','POST',{});if(!normalizeRecoveryCode(result.recoveryCode))throw new Error('没有收到完整恢复码，请重新生成。');clearQuickStart();if(pendingClub)forgetRegistrationAttempt(pendingClub);closeDialog();render();showRecoveryCode(result.recoveryCode,{offerInvite:!!pendingClub&&!!state.board&&state.board.me===state.board.club.ownerId});});};}
function openBindLegacy(clubId){if(!state.account){openRecoveryLogin();return;}const selected=clubId||state.legacyClub?.id,legacy=state.legacyClub?.id===selected?state.legacyClub:state.claims.find(c=>c.id===selected);if(!legacy||!validClub(selected)||!validToken(legacy.token)){toast('本设备没有找到这张原名片，请回到原设备连接。');return;}modal('连接本设备的原名片？',`<form id="bind-legacy-form" class="form"><p>将 <strong>${esc(legacy.name||state.board?.club.name)}</strong> 中 <strong>${esc(legacy.nickname)}</strong> 的原名片连接到当前身份 <strong>${esc(state.account.displayName)}</strong>。</p><p class="profile-help">原头像、记录和群主身份都会保留。只有本设备持有的原名片可以连接；同群里的其他名片不会合并。</p>${actionButtons('确认连接这张原名片')}</form>`,'MY TENNIS IDENTITY');$('#bind-legacy-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{await request(`/api/auth/bind?club=${encodeURIComponent(selected)}`,'POST',{legacySessionToken:legacy.token});rememberLegacyClaims({},selected);resetView();if(!state.invite){state.club=selected;history.replaceState(null,'',`${appBase}#c=${encodeURIComponent(selected)}`);}closeDialog();render();await loadAccount();await load();toast('原名片已连接，继续使用原来的记录。');});};}
async function logout(button){button.disabled=true;try{await request('/api/auth/logout','POST',{});markMigrationSignedOut();forgetDeviceSessions();clearQuickStart();resetView();state.account=null;state.clubs=[];state.createDraft=null;state.invite=null;state.club=null;state.invalidInvite=false;state.authReady=true;state.authError=null;state.linkIntent=null;history.replaceState(null,'',appBase);if(dialog.open)closeDialog();render();toast('已退出本设备。用本人恢复码可以找回名片。');}catch(e){toast(e.message);button.disabled=false;}}
function openProfile(){if(!state.account&&!me()){openEmailAuth('signup');return;}const m=me();if(!m&&registrationAttempt(state.board?.club.id)){openSaveIdentity(state.board.club.id);return;}if(!m&&state.legacyClub){openBindLegacy(state.legacyClub.id);return;}modal(m?'我的球友名片':'给自己一张球友名片',`<form id="profile-form" class="form"><div class="avatar-editor">${avatar(m,true)}<div><label for="avatar-file">我的头像 <span class="optional">选填</span></label><input type="file" id="avatar-file" accept="image/*"><p class="form-helper">选择图片后会显示预览。</p></div></div><div><label for="nickname">群昵称</label><input id="nickname" name="nickname" required maxlength="20" value="${esc(m?.nickname||accountAlias())}" placeholder="搭子们平时怎么叫你？" autocomplete="nickname"></div><div><label for="bio">我的球场宣言 <span class="optional">选填</span></label><input id="bio" name="bio" value="${esc(m?.bio||'')}" maxlength="80" placeholder="比如：反手还在练，热情已经满格。"></div><p class="profile-help">${state.account?`这张名片会连接身份 ${esc(state.account.displayName)}，平时自动进入，换设备可用恢复码找回。`:'这个微信或浏览器会记住你的名片。保存免密码身份后，换设备可用私密恢复码找回头像和记录。'}</p>${m&&!state.account?'<button type="button" class="secondary" data-action="register">保存我的身份（免密码）</button>':''}${m?'<div class="form-actions"><button type="button" class="text-button" data-action="monthly-rating">更新月度能力</button><button type="button" class="text-button" data-action="personal-share">管理公开球员卡</button></div>':''}${actionButtons(m?'保存名片':'加入这群搭子')}</form>`,'MY PLAYER CARD');let selected=null,preview=null;$('#avatar-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const error=$('#profile-form .form-error'),saveButton=$('#profile-form button[type=submit]');saveButton.disabled=true;try{selected=await avatarBlob(file);if(preview)URL.revokeObjectURL(preview);preview=URL.createObjectURL(selected);$('#profile-form .avatar').innerHTML=`<img src="${preview}" alt="新头像预览">`;error.textContent='';}catch(e){selected=null;error.textContent=e.message;}finally{saveButton.disabled=false;}};$('#profile-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;await submit(f,async()=>{await request('/api/profile','POST',Object.fromEntries(new FormData(f)));if(selected){const r=await apiFetch('/api/avatar',{method:'POST',headers:{'Content-Type':selected.type},body:selected});if(!r.ok){const result=await r.json();throw new Error(`昵称已保存，头像未上传成功：${result.error}`);}}closeDialog();if(preview)URL.revokeObjectURL(preview);await loadAccount();await load();toast(m?'名片更新好了。':'入场了，下一场一起打！');if(!m&&!state.account)await autoSaveIdentity();});};}
async function avatarBlob(file){if(file.size>15*1024*1024)throw new Error('这张图片太大了，请选择 15MB 以内的图片。');let image,objectUrl;try{objectUrl=URL.createObjectURL(file);image=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=objectUrl;});const canvas=document.createElement('canvas');canvas.width=512;canvas.height=512;const context=canvas.getContext('2d');const size=Math.min(image.width,image.height);context.fillStyle='#fff';context.fillRect(0,0,512,512);context.drawImage(image,(image.width-size)/2,(image.height-size)/2,size,size,0,0,512,512);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.88));if(!blob)throw new Error();return blob;}catch{throw new Error('这张图片打不开，请换一张 JPG、PNG 或 WebP 图片。');}finally{if(objectUrl)URL.revokeObjectURL(objectUrl);}}
function openRecord(recordId,trainingMode=false){if(!requireMember())return;const r=findRecord(recordId);if(recordId&&!r){toast('记录暂时没有加载出来，请刷新后再试。');return;}const formId=r?.id||crypto.randomUUID();modal(r?'修改这次记录':trainingMode?'记录训练':'记一场球',`<form id="record-form" class="form"><div class="row"><div><label for="play-date">打球日期</label><input type="date" id="play-date" name="playDate" value="${r?.play_date||state.board.today||today()}" max="${state.board.today||today()}" required></div><div><label for="minutes">训练 / 打球时长 <span class="optional">分钟</span></label><input type="number" id="minutes" name="minutes" value="${r?.minutes||90}" min="1" max="1440" step="1" required inputmode="numeric"></div></div>${Growth.form(r,trainingMode)}<div><label for="partners">搭档 <span class="optional">选填</span></label><input id="partners" name="partners" value="${esc(r?.partners||'')}" placeholder="和谁一起打的？可以写多个昵称。" maxlength="120" list="partner-list"><datalist id="partner-list">${state.board.members.filter(m=>m.id!==state.board.me).map(m=>`<option value="${esc(m.nickname)}"></option>`).join('')}</datalist></div><div><label for="venue">球场 <span class="optional">选填</span></label><input id="venue" name="venue" maxlength="60" value="${esc(r?.venue||'')}" placeholder="今天在哪儿挥拍？"></div><div><label>今天的状态</label><div class="mood-options">${moods.map((m,i)=>`<label><input type="radio" name="mood" value="${m}" ${(r?.mood||moods[0])===m?'checked':''}>${m}</label>`).join('')}</div></div><div><label for="record-note">打球感想 <span class="optional">选填，500 字以内</span></label><textarea id="record-note" name="note" maxlength="500" placeholder="一记好球、一次进步，或者球场上发生的趣事…">${esc(r?.note||'')}</textarea></div>${Hexagon.form(r)}${actionButtons(r?'保存修改':'记住这场球')}</form>`,'A GOOD DAY ON COURT');Hexagon.bindForm($('#record-form'));Growth.bindForm($('#record-form'));$('#record-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;await submit(f,async()=>{const data={...Object.fromEntries(new FormData(f)),id:formId,skills:Hexagon.readForm(f),training:Growth.readTraining(f)};await request(r?`/api/records/${r.id}`:'/api/records',r?'PATCH':'POST',data);closeDialog();Growth.model.page=0;await load();toast(r?'这次记录改好了。':data.training?'训练记下了，下次接着练！':'这场记住了，下次继续！');});};}
function openCulture(){if(!requireMember())return;const id=crypto.randomUUID();modal('留下一句群内梗',`<form id="culture-form" class="form"><p class="subtext">群里的口头禅、球场上的名场面，都值得贴在这面墙上。</p><div><label for="culture-content">只有你们懂的那一句</label><textarea id="culture-content" name="content" maxlength="160" required placeholder="写一句你们群里才懂的梗，最多 160 字。"></textarea></div>${actionButtons('贴到群内梗墙')}</form>`,'ONLY WE GET IT');$('#culture-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;await submit(f,async()=>{await request('/api/culture','POST',{...Object.fromEntries(new FormData(f)),id});closeDialog();state.tab='culture';await load();toast('这句梗，留在群里了。');});};}
function openSettings(){const c=state.board.club;if(c.ownerId!==state.board.me)return;modal('群名和口号',`<form id="settings-form" class="form"><div><label for="edit-club-name">群名</label><input id="edit-club-name" name="name" required maxlength="24" value="${esc(c.name)}"></div><div><label for="edit-slogan">群口号 <span class="optional">选填</span></label><textarea id="edit-slogan" name="slogan" maxlength="80" placeholder="写一句属于你们的话。">${esc(c.slogan)}</textarea></div>${actionButtons('保存群设置')}</form>`);$('#settings-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;await submit(f,async()=>{await request('/api/club','PATCH',Object.fromEntries(new FormData(f)));closeDialog();await load();toast('现在，更像你们的群了。');});};}
function shareUrl(base=appBase){const invite=state.shareInvite;return validToken(invite)?`${base}#g=${encodeURIComponent(invite)}`:null;}
async function openInvite(){try{if(state.board?.me!==state.board?.club.ownerId){toast('请让管理员生成群邀请。');return;}if(!state.shareInvite){if(!requireMember())return;const result=await request('/api/invite','POST',{});if(!validToken(result.invite))throw new Error('邀请链接还没有生成，请重试。');state.shareInvite=result.invite;}const url=shareUrl();if(!url)throw new Error('请先进入一个群，再邀请搭子。');modal('叫搭子们进来',`<p>把这条邀请链接发到微信群，大家点开后，就能建立名片、记录打球。</p><textarea class="share-url" id="invite-url" readonly aria-label="群邀请链接">${esc(url)}</textarea><p class="share-warning">邀请 7 天内有效。球友注册、登录并加入后，才能查看组内内容。微信内可以长按复制链接，或使用右上角菜单分享。</p>${!state.account&&me()?'<div class="invite-account-note"><strong>也为自己留一个登录入口。</strong><p>保存免密码身份，换设备可用私密恢复码找回这张名片和这个群。</p><button class="secondary" data-action="register">保存我的身份（免密码）</button></div>':''}<div class="form-actions"><button class="primary" data-action="copy-invite">${icon('share')}复制群邀请链接</button>${!remoteApi?'<button class="secondary" data-action="copy-pages-invite">复制 GitHub 邀请链接</button>':''}</div>`,'SEE YOU ON COURT');}catch(e){toast(e.message);}}
async function copyInvite(url=shareUrl()){if(!url){toast('邀请链接还没有生成，请重试。');return;}const input=$('#invite-url');if(input)input.value=url;try{await navigator.clipboard.writeText(url);toast('邀请链接复制好了，发到微信群吧。');}catch{input.focus();input.select();try{if(document.execCommand('copy'))toast('邀请链接复制好了。');else toast('长按已选中的链接，选择复制。');}catch{toast('长按已选中的链接，选择复制。');}}}
function confirmDelete(type,id){const r=type==='record'?findRecord(id):state.board.culture.find(p=>p.id===id);if(!r)return;modal(type==='record'?'删除这场记录？':'删除这句群内梗？',`<form id="delete-form" class="form"><p>${type==='record'?`${day(r.play_date)} · ${r.minutes} 分钟的打球记录及收到的鼓掌会一起删除。`:'这句话会从群内梗墙移除。'}删除后无法恢复。</p>${actionButtons('确认删除')}</form>`,'ONE LAST CHECK');$('#delete-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{await request(`/api/${type==='record'?'records':'culture'}/${id}`,'DELETE');closeDialog();await load();toast('已删除。');});};}
document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
  if(action==='login')openAccess();
  else if(action==='register')openSaveIdentity(b.dataset.club);
  else if(action==='bind-legacy')openBindLegacy(b.dataset.club||state.legacyClub?.id);
  else if(action==='identity')openIdentity();
  else if(action==='recovery-help')openRecoveryHelp();
  else if(action==='renew-recovery')openRenewRecovery();
  else if(action==='copy-recovery')await copyRecovery();
  else if(action==='download-recovery')downloadRecovery();
  else if(action==='recovery-invite'){closeDialog();await openInvite();}
  else if(action==='logout')await logout(b);
  else if(action==='home'){if(location.hash)location.hash='';else await initialize();}
  else if(action==='open-club'&&validClub(b.dataset.club))location.hash=`c=${encodeURIComponent(b.dataset.club)}`;
  else if(action==='refresh-auth'){b.disabled=true;await initialize();}
  else if(action==='link-pages')beginPagesLink();
  else if(action==='pages-return')location.replace(`${PAGES_BASE}#g=${encodeURIComponent(state.invite)}`);
  else if(action==='confirm-pages-link'){if(!canUsePagesBridge){openRecoveryLogin();return;}if(state.account){toast('请在 GitHub 页面使用私密恢复码找回身份。');return;}b.disabled=true;try{const result=await request('/api/pages-session','POST',{});if(!validToken(result.sessionToken))throw new Error('名片连接未完成，请重试。');location.replace(`${PAGES_BASE}#g=${encodeURIComponent(state.invite)}&session=${result.sessionToken}&state=${state.linkIntent}`);}catch(err){toast(err.message);b.disabled=false;}}
  else if(action==='close')closeDialog();
  else if(action==='tab'){state.tab=b.dataset.tab;render();loadAvatars();window.scrollTo({top:0});}
  else if(action==='profile')openProfile();
  else if(action==='record')openRecord();
  else if(action==='training')openRecord(undefined,true);
  else if(action==='checkin'){if(!requireMember())return;b.disabled=true;try{const result=await request('/api/checkins','POST',{});await load();toast(result.alreadyChecked?'今天已经签到啦。':'签到成功，今天又坚持了一点！');}catch(err){toast(err.message);b.disabled=false;}}
  else if(action==='growth-month'){Growth.model.month=b.dataset.month;b.disabled=true;await loadGrowth();render();loadAvatars();}
  else if(action==='growth-page'){Growth.model.page=Number(b.dataset.page);b.disabled=true;await loadGrowth();render();loadAvatars();$('.growth-timeline')?.scrollIntoView({block:'start'});}
  else if(action==='use-training-plan'){const input=$('#training-content'),plan=Growth.model.data?.nextPlan?.next_plan||'';if(input&&plan){input.value=input.value.trim()?input.value.trim()+'\n'+plan:plan;input.focus();}}
  else if(action==='edit-record')openRecord(b.dataset.id);
  else if(action==='view-hex')openHexagon(b.dataset.id);
  else if(action==='culture')openCulture();
  else if(action==='settings')openSettings();
  else if(action==='invite'){b.disabled=true;await openInvite();b.disabled=false;}
  else if(action==='copy-invite')await copyInvite();
  else if(action==='copy-pages-invite')await copyInvite(shareUrl(PAGES_BASE));
  else if(action==='delete-record')confirmDelete('record',b.dataset.id);
  else if(action==='delete-culture')confirmDelete('culture',b.dataset.id);
  else if(action==='refresh'){b.disabled=true;await load();}
  else if(action==='cheer'){if(!requireMember())return;b.disabled=true;try{await request('/api/cheers','POST',{recordId:b.dataset.id,emoji:b.dataset.emoji});await load();}catch(e){toast(e.message);b.disabled=false;}}
});
async function initialize(){render();if(state.publicToken){await loadPublicCard();return;}if(state.invalidInvite)return;const ready=await loadAccount();if(!ready){render();return;}render();if(hasClub())await load();if(state.linkFailed)toast(canUsePagesBridge?'名片连接未完成，请重新选择使用原页面的名片。':'请使用私密恢复码找回身份，本设备已保存的名片会自动连接。');}
window.addEventListener('hashchange',async()=>{const params=new URLSearchParams(location.hash.slice(1));Object.assign(state,inviteRoute(params));state.publicToken=validToken(params.get('p'))?params.get('p'):null;state.publicCard=null;state.publicError=null;state.club=validClub(params.get('c'))?params.get('c'):null;if(remoteApi&&!state.invalidInvite){const token=readSession(state.invite);state.session=validToken(token)?token:null;}resetView();if(dialog.open)closeDialog();render();if(state.publicToken){await loadPublicCard();return;}if(state.invalidInvite)return;if(!state.authReady||!hasClub())await initialize();else await load();});
setInterval(()=>{if(hasClub()&&state.board&&!dialog.open&&document.visibilityState==='visible')load({quiet:true});},30000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&hasClub()&&!dialog.open)load({quiet:true});});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const [name,tab] of [['view_court_records','feed'],['view_player_cards','members'],['view_group_culture','culture']]){try{Promise.resolve(document.modelContext.registerTool({name,title:tabs.find(t=>t[0]===tab)[1],description:'打开对应的群视图并返回当前共享内容；不创建或修改记录。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},async execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('此操作不接受参数。');if(!hasClub())throw new Error('请先打开自己的群或通过群邀请链接进入。');await load();if(state.error)throw new Error(state.error);if(!state.board?.me)throw new Error('请先登录并加入小组。');state.tab=tab;render();return {club:state.board.club.name,view:tab,items:tab==='feed'?state.board.records:tab==='members'?state.board.members:state.board.culture};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
function openHexagon(recordId){
  const record=findRecord(recordId),scores=Hexagon.scores(record);
  if(!scores)return;
  modal('这场球的六边形',`<p class="hex-detail-meta">${esc(member(record.member_id)?.nickname||record.nickname)} · ${day(record.play_date)} · ${record.minutes} 分钟</p><div class="hex-detail-chart">${Hexagon.chart(scores,'本场六维自评')}${Hexagon.total(scores)}</div><p class="hex-detail-highlight">${Hexagon.highlight(scores)}</p><p class="hex-explainer">本场自评：0 起步 · 5 基本到位 · 10 很满意 · 待测为空<br>记录当场的感受，每一场都有自己的形状。</p>${record.member_id===state.board.me?`<div class="form-actions"><button class="secondary" data-action="edit-record" data-id="${record.id}">修改这场自评</button></div>`:''}`,'MY SIX-SIDED STORY');
}
document.addEventListener('change',e=>{if(e.target.id==='growth-metric'){Growth.model.metric=e.target.value;render();loadAvatars();}});
initialize();
